import {spawn} from 'node:child_process';
import {openSync,appendFileSync} from 'node:fs';
const [name,...argv]=process.argv.slice(2),dir='_scratch/ar-current/evidence';
const start=new Date().toISOString();const fd=openSync(dir+'/'+name+'.txt','w');const p=spawn('rtk',['proxy',...argv],{stdio:['ignore',fd,fd]});
p.on('exit',(code,signal)=>{appendFileSync(dir+'/commands.jsonl',JSON.stringify({start,end:new Date().toISOString(),argv,code,signal,log:name+'.txt'})+'\n');console.log(name+': exit '+code);process.exitCode=code??1;});

import {readFileSync,appendFileSync} from 'node:fs';
const mode=process.argv[2],file=process.argv[3];
const port=mode==='main'?9736:9735;
const targets=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();
const target=targets.find(t=>mode==='main'||t.type==='page');
const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});
let id=0;const pending=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{const i=++id;pending.set(i,{resolve,reject});ws.send(JSON.stringify({id:i,method,params}));});
try {
 if(mode!=='main'){await send('Emulation.setFocusEmulationEnabled',{enabled:true});try{await send('Emulation.setPageVisibilityOverride',{visibility:'visible'});}catch{}}
 const expression=readFileSync(file,'utf8');
 const result=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true,timeout:700000});
 const receipt={at:new Date().toISOString(),mode,file,...result};
 appendFileSync('_scratch/ar-current/evidence/cdp.jsonl',JSON.stringify(receipt)+'\n');
 if(result.exceptionDetails){console.error(JSON.stringify(result.exceptionDetails));process.exitCode=1;}else console.log(JSON.stringify(result.result.value));
}finally{ws.close();}

import {spawn} from 'node:child_process';
import {openSync,writeFileSync,existsSync} from 'node:fs';
const here=process.cwd(), dir=here+'/_scratch/ar-current';
const children=[];
function launch(cmd,args,env,log){const p=spawn(cmd,args,{cwd:here,env:{...process.env,...env},stdio:['ignore',openSync(dir+'/'+log,'w'),'pipe']});p.stderr.pipe(process.stderr);children.push(p);return p;}
const renderer=launch(process.execPath,['node_modules/@angular/cli/bin/ng.js','serve','--port','4735','--prebundle=false'],{},'renderer.log');
const pause=ms=>new Promise(r=>setTimeout(r,ms));
let app;
try {
 for(let n=0;n<150;n++){try{if((await fetch('http://localhost:4735')).ok)break;}catch{}await pause(1000);if(n===149)throw Error('Renderer startup deadline');}
 app=launch(here+'/node_modules/electron/dist/Electron.app/Contents/MacOS/Electron',['.','--no-sandbox','--js-flags=--max-old-space-size=8192','--remote-debugging-port=9735','--inspect=9736'],{AIO_DEV_USER_DATA_PATH:'/tmp/aio-lt-queue-3af326de',PORT:'4735'},'electron.log');
 writeFileSync(dir+'/processes.json',JSON.stringify({at:new Date(),renderer:renderer.pid,app:app.pid,supervisor:process.pid}));
 console.log('Owned app launch',app.pid);
 await new Promise((resolve,reject)=>{app.once('exit',resolve);app.once('error',reject);});
} finally {
 for(const p of children){if(p.exitCode===null&&p.signalCode===null)p.kill('SIGTERM');}
 await pause(2000);
 writeFileSync(dir+'/process-exits.json',JSON.stringify({at:new Date(),children:children.map(p=>({pid:p.pid,exit:p.exitCode,signal:p.signalCode}))}));
}

import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {gzipSync} from 'node:zlib';
const root=process.cwd(),runtime=root+'/_scratch/ar-current',evidence=runtime+'/evidence';
const finalDir=root+'/docs/plans/2026-09-27-livetest-agent-runtime-residuals_evidence/2026-10-27-current';
const report='/Users/suas/work/orchestrat0r/ai-orchestrator/docs/plans/2026-09-27-livetest-agent-runtime-residuals_livetest.md';
const hash=p=>createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const json=p=>JSON.parse(fs.readFileSync(p,'utf8'));
const write=(name,v)=>fs.writeFileSync(evidence+'/'+name,JSON.stringify(v,null,2)+'\n');
const commands=fs.readFileSync(evidence+'/commands.jsonl','utf8').trim().split('\n').map(JSON.parse);
if(!commands.some(c=>JSON.stringify(c.argv)===JSON.stringify(['npm','run','test:quiet'])))throw Error('Full suite has no final command receipt');
const rows=fs.readFileSync(evidence+'/cdp.jsonl','utf8').trim().split('\n').map(JSON.parse);
const owned=json(runtime+'/processes.json'),cleanup=rows.find(x=>x.file.endsWith('/main-cleanup.js')).result.value;
const provider=json(evidence+'/log-provider-pids.json').pids;
const pids=[...new Set([owned.supervisor,owned.renderer,owned.app,cleanup.warmPid,...cleanup.metrics.map(m=>m.pid),...provider])].filter(Boolean);
const liveness=pids.map(pid=>{try{process.kill(pid,0);return {pid,state:'alive'};}catch(e){return {pid,state:e.code==='ESRCH'?'gone':'unknown',code:e.code};}});
if(liveness.some(p=>p.state!=='gone'))throw Error('Owned app PID remains or liveness unknown');
const endpoints=[];for(const port of [4735,9735,9736]){try{await fetch('http://127.0.0.1:'+port);endpoints.push({port,state:'responding'});}catch{endpoints.push({port,state:'closed'});}}
if(endpoints.some(p=>p.state!=='closed'))throw Error('Owned app endpoint still responds');
write('process-exits.json',json(runtime+'/process-exits.json'));
write('cleanup-preflight.json',{at:new Date().toISOString(),liveness,endpoints});
const probes=json(evidence+'/probe-sources.json');probes.scripts.push({file:'finalize.mjs',source:fs.readFileSync(import.meta.filename,'utf8')});write('probe-sources.json',probes);
const fullLogs=[];for(const file of fs.readdirSync(root+'/_scratch').filter(n=>/^test-run.*\.log$/.test(n))){const p=root+'/_scratch/'+file,data=fs.readFileSync(p),target=file+'.gz';fs.writeFileSync(evidence+'/'+target,gzipSync(data));fullLogs.push({original:file,retained:target,bytes:data.length,sha256:hash(p)});}
write('full-log-receipts.json',fullLogs);
const sourcePaths=execFileSync('git',['diff','--name-only','80412201a...HEAD','--','src'],{encoding:'utf8'}).trim().split('\n');
const compiled=['dist/main/cli/adapters/claude-cli-permission-details.js','dist/main/instance/lifecycle/instance-spawn-preflight-chain.js','dist/main/orchestration/headless-review-runner.js','dist/main/review/review-execution-host.js'];
const seal={sealedBeforeCleanupAt:new Date().toISOString(),head:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),base:'80412201a07ec93cefb9a4b6ddb06579ad314d75',report:{path:report,sha256:hash(report)},sources:sourcePaths.map(path=>({path,sha256:hash(root+'/'+path)})),compiled:compiled.map(path=>({path,sha256:hash(root+'/'+path)})),sourceEditedThisTurn:false};
write('source-seal.json',seal);
if(hash(report)!==seal.report.sha256)throw Error('Report changed after seal');
fs.renameSync(evidence,finalDir);
const paths=[root+'/dist','/tmp/aio-lt-queue-3af326de','/var/folders/0n/fs5yys3d0vg0c838h75hyrm00000gn/T/codex-aio-IynzUJ',root+'/.aio-loop-state/loop-1793074597371-1cfc02db',root+'/_scratch'];
const removed=[];for(const path of paths){const existed=fs.existsSync(path);if(existed&&fs.lstatSync(path).isSymbolicLink())throw Error('Refusing symlink removal');if(existed)fs.rmSync(path,{recursive:true,maxRetries:4,retryDelay:100});removed.push({path,existed,absent:!fs.existsSync(path)});}
const cleanupReceipt={at:new Date().toISOString(),liveness,endpoints,removed,processExits:json(finalDir+'/process-exits.json'),settingsRestored:true,instancesRemaining:0,automationsRemaining:0,dependencies:'No dependency installs or browser downloads in this continuation. Pre-existing coordinator-supplied node_modules and cache trees retained.',copies:'No copied checkout, source tree or dependency tree; no branch/worktree/commit/stash created',limitations:'Host denies ps; recorded app/utility/warm/provider PIDs checked by kill(pid,0). No global process-list claim.'};
fs.writeFileSync(finalDir+'/cleanup-receipt.json',JSON.stringify(cleanupReceipt,null,2)+'\n');
seal.finalizedAfterCleanupAt=new Date().toISOString();seal.artifacts=fs.readdirSync(finalDir).filter(n=>n!=='source-seal.json').map(file=>({file,sha256:hash(finalDir+'/'+file)}));
fs.writeFileSync(finalDir+'/source-seal.json',JSON.stringify(seal,null,2)+'\n');
console.log(JSON.stringify({sealed:true,endpointsClosed:true,allRecordedPidsGone:true,removed:removed.length,allPathsAbsent:removed.every(x=>x.absent),evidence:finalDir}));
